/* ───────────────────────── Orrery design tokens ───────────────────────── */
@theme {
  --color-ink: #0E0F13;
  --color-bone: #F2EFE8;
  --color-ultramarine: #2F3BFF;
  --color-amber: #FFB000;

  --font-display: var(--font-instrument-serif), "Times New Roman", serif;
  --font-body: var(--font-inter-tight), system-ui, sans-serif;
  --font-mono: var(--font-geist-mono), ui-monospace, monospace;

  --ease-out: cubic-bezier(0.23, 1, 0.32, 1);
  --ease-deck: cubic-bezier(0.77, 0, 0.175, 1);
}

:root {
  --ink-muted: color-mix(in oklab, var(--color-ink) 62%, var(--color-bone));
  --ink-line: color-mix(in oklab, var(--color-ink) 16%, var(--color-bone));
  --bone-muted: color-mix(in oklab, var(--color-bone) 62%, var(--color-ink));
  --bone-line: color-mix(in oklab, var(--color-bone) 18%, var(--color-ink));
  --gutter: clamp(20px, 5vw, 80px);
  --topbar: 76px;
  --deck-duration: 700ms;
}

/* ───────────────────────── Base ───────────────────────── */
.orr-body {
  margin: 0;
  background: var(--color-bone);
  color: var(--color-ink);
  font-family: var(--font-body);
  font-size: 1.0625rem;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

.orr-body ::selection {
  background: var(--color-ultramarine);
  color: var(--color-bone);
}

.orr-body :focus-visible {
  outline: 2px solid var(--color-ultramarine);
  outline-offset: 3px;
}

/* ───────────────────────── Type ───────────────────────── */
.orr-display {
  font-family: var(--font-display);
  font-weight: 400;
  font-size: clamp(3.5rem, min(11vw, 17vh), 11.5rem);
  line-height: 0.88;
  letter-spacing: -0.025em;
  margin: 0;
}

.orr-h2 {
  font-family: var(--font-display);
  font-weight: 400;
  font-size: clamp(2.75rem, min(6.2vw, 9vh), 6.75rem);
  line-height: 0.95;
  letter-spacing: -0.02em;
  margin: 0;
  text-wrap: balance;
}

.orr-h2 em,
.orr-display em {
  font-style: italic;
}

/* Explicit headline lines never re-wrap, so the fallback font can't change the line count (no layout shift). */
.orr-line {
  display: block;
  white-space: nowrap;
}

.orr-h3 {
  font-family: var(--font-display);
  font-weight: 400;
  font-size: clamp(1.6rem, 2.2vw, 2.25rem);
  line-height: 1.05;
  margin: 0;
}

.orr-lead {
  font-size: clamp(1.125rem, 1.35vw, 1.375rem);
  line-height: 1.5;
  max-width: 34ch;
  margin: 0;
  text-wrap: pretty;
}

.orr-label {
  font-family: var(--font-mono);
  font-size: 0.75rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.orr-accent {
  color: var(--color-ultramarine);
}

/* ───────────────────────── Top bar ───────────────────────── */
.orr-topbar {
  position: fixed;
  inset: 0 0 auto 0;
  z-index: 20;
  height: var(--topbar);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 var(--gutter);
  pointer-events: none;
  color: var(--topbar-color, var(--color-ink));
  background: var(--topbar-bg, var(--color-bone));
  border-bottom: 1px solid var(--topbar-line, var(--ink-line));
  transition:
    color 300ms var(--ease-out),
    background-color 300ms var(--ease-out);
}

.orr-topbar > * {
  pointer-events: auto;
}

.orr-logo {
  font-family: var(--font-display);
  font-size: 1.875rem;
  line-height: 1;
  color: inherit;
  text-decoration: none;
  letter-spacing: -0.01em;
}

.orr-logo span {
  color: var(--color-ultramarine);
}

.orr-btn {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  height: 44px;
  padding: 0 20px;
  border-radius: 999px;
  border: 1px solid currentColor;
  color: inherit;
  background: transparent;
  font-family: var(--font-mono);
  font-size: 0.75rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  text-decoration: none;
  cursor: pointer;
  transition:
    background-color 200ms var(--ease-out),
    color 200ms var(--ease-out),
    border-color 200ms var(--ease-out),
    transform 160ms var(--ease-out);
}

.orr-btn:active {
  transform: scale(0.97);
}

.orr-btn--solid {
  background: var(--color-ultramarine);
  border-color: var(--color-ultramarine);
  color: var(--color-bone);
}

@media (hover: hover) and (pointer: fine) {
  .orr-btn:hover {
    background: var(--color-ink);
    border-color: var(--color-ink);
    color: var(--color-bone);
  }
  [data-tone="ink"] .orr-btn:hover,
  .orr-topbar[data-tone="ink"] .orr-btn:hover {
    background: var(--color-bone);
    border-color: var(--color-bone);
    color: var(--color-ink);
  }
  .orr-btn--solid:hover {
    background: var(--color-ink);
    border-color: var(--color-ink);
  }
}

.orr-topbar[data-tone="ink"] {
  --topbar-color: var(--color-bone);
  --topbar-bg: var(--color-ink);
  --topbar-line: var(--bone-line);
}

/* ───────────────────────── Deck ───────────────────────── */
.orr-deck {
  position: relative;
}

.orr-slide {
  position: relative;
  min-height: 100svh;
  box-sizing: border-box;
  padding: calc(var(--topbar) + 24px) var(--gutter) 88px;
  display: flex;
  flex-direction: column;
  background: var(--color-bone);
  color: var(--color-ink);
}

.orr-slide[data-tone="ink"] {
  background: var(--color-ink);
  color: var(--color-bone);
}

.orr-slide-inner {
  flex: 1;
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  column-gap: 24px;
  row-gap: 32px;
  align-content: center;
}

.orr-eyebrow {
  grid-column: 1 / -1;
  display: flex;
  gap: 12px;
  align-items: center;
  color: var(--ink-muted);
}

.orr-slide[data-tone="ink"] .orr-eyebrow {
  color: var(--bone-muted);
}

.orr-eyebrow::before {
  content: "";
  width: 28px;
  height: 1px;
  background: currentColor;
}

/* Counter + chapter rail (colours follow the active slide's tone) */
.orr-counter {
  position: fixed;
  left: var(--gutter);
  bottom: 24px;
  z-index: 20;
  margin: 0;
  padding: 6px 12px;
  border-radius: 999px;
  border: 1px solid var(--ink-line);
  background: var(--color-bone);
  color: var(--color-ink);
  font-family: var(--font-mono);
  font-size: 0.75rem;
  letter-spacing: 0.08em;
  font-variant-numeric: tabular-nums;
  transition:
    color 300ms var(--ease-out),
    background-color 300ms var(--ease-out),
    border-color 300ms var(--ease-out);
}

@media (max-width: 599px) {
  .orr-counter {
    display: none;
  }
}

.orr-counter[data-tone="ink"] {
  background: var(--color-ink);
  border-color: var(--bone-line);
  color: var(--color-bone);
}

.orr-rail {
  position: fixed;
  right: var(--gutter);
  top: 50%;
  transform: translateY(-50%);
  z-index: 20;
  display: none;
  --rail-fg: var(--color-ink);
  --rail-muted: color-mix(in oklab, var(--color-ink) 34%, var(--color-bone));
}

.orr-rail[data-tone="ink"] {
  --rail-fg: var(--color-bone);
  --rail-muted: color-mix(in oklab, var(--color-bone) 34%, var(--color-ink));
}

.orr-rail ol {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 2px;
}

.orr-rail button {
  all: unset;
  box-sizing: border-box;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 12px;
  min-height: 28px;
  cursor: pointer;
  font-family: var(--font-mono);
  font-size: 0.6875rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--rail-muted);
  transition: color 300ms var(--ease-out);
}

.orr-rail button span {
  opacity: 0;
  transform: translateX(6px);
  transition:
    opacity 200ms var(--ease-out),
    transform 200ms var(--ease-out);
}

.orr-rail button::after {
  content: "";
  width: 14px;
  height: 1px;
  background: currentColor;
  transition: width 240ms var(--ease-out);
}

.orr-rail button[aria-current="step"] {
  color: var(--rail-fg);
}

.orr-rail button[aria-current="step"] span,
.orr-rail:hover button span,
.orr-rail button:focus-visible span {
  opacity: 1;
  transform: none;
}

.orr-rail:hover button {
  color: var(--rail-fg);
}

.orr-rail button[aria-current="step"]::after {
  width: 34px;
}

/* Desktop keynote mode: slides stack in place and wipe in. */
/* KEYNOTE: keep in sync with KEYNOTE_QUERY in deck/Deck.tsx */
@media (min-width: 900px) and (min-height: 760px) and (prefers-reduced-motion: no-preference) {
  html:has(.orr-deck) {
    overflow: hidden;
    overscroll-behavior: none;
  }

  .orr-deck {
    position: fixed;
    inset: 0;
    overflow: hidden;
  }

  .orr-slide {
    position: absolute;
    inset: 0;
    min-height: 0;
    will-change: clip-path, transform;
    transition:
      clip-path var(--deck-duration) var(--ease-deck),
      transform var(--deck-duration) var(--ease-deck);
  }

  .orr-deck:not([data-ready]) .orr-slide {
    transition: none;
  }

  .orr-slide[data-state="past"] {
    z-index: 1;
    clip-path: inset(0 0 0 0);
    transform: translateY(-7vh);
  }

  .orr-slide[data-state="active"] {
    z-index: 2;
    clip-path: inset(0 0 0 0);
    transform: none;
  }

  .orr-slide[data-state="future"] {
    z-index: 3;
    clip-path: inset(100% 0 0 0);
    transform: none;
  }

  .orr-rail {
    display: block;
  }

  /* Keynote mode: transparent bar, and room on the right for the chapter rail. */
  .orr-topbar {
    --topbar-bg: transparent;
    --topbar-line: transparent;
  }

  .orr-slide {
    padding-right: calc(var(--gutter) + 150px);
  }
}

/* ───────────────────────── Shared slide pieces ───────────────────────── */
.orr-placeholder {
  display: grid;
  place-items: center;
  background:
    repeating-linear-gradient(135deg, transparent 0 14px, color-mix(in oklab, currentColor 5%, transparent) 14px 15px),
    color-mix(in oklab, currentColor 4%, transparent);
  border: 1px dashed color-mix(in oklab, currentColor 28%, transparent);
  color: inherit;
}

.orr-placeholder .orr-label {
  opacity: 0.6;
  align-self: start;
  justify-self: start;
  padding: 12px 14px;
}

.orr-art {
  display: block;
  width: 100%;
  overflow: hidden;
  border-radius: 2px;
}

.orr-art img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.orr-art--title {
  aspect-ratio: 4 / 3.4;
}

.orr-art--portrait {
  aspect-ratio: 4 / 5;
}

.orr-art--card {
  aspect-ratio: 4 / 3;
}

kbd {
  font-family: var(--font-mono);
  font-size: 0.85em;
  padding: 1px 6px;
  border: 1px solid currentColor;
  border-radius: 4px;
}

/* Mobile/flow default: every block spans the full width. */
.orr-slide-inner > * {
  grid-column: 1 / -1;
  min-width: 0;
}

/* ───────────────────────── 01 Title ───────────────────────── */
.orr-title__copy {
  display: flex;
  flex-direction: column;
  gap: 28px;
}

.orr-title__kicker {
  color: var(--color-ultramarine);
}

.orr-title__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

.orr-title__art {
  margin: 0;
}

.orr-title__hint {
  color: var(--ink-muted);
  display: none;
}

/* ───────────────────────── 02 Problem ───────────────────────── */
.orr-problem__art {
  margin: 0;
}

.orr-problem__copy {
  display: flex;
  flex-direction: column;
  gap: 40px;
}

.orr-numbered {
  list-style: none;
  margin: 0;
  padding: 0;
  border-top: 1px solid var(--ink-line);
}

.orr-numbered li {
  display: grid;
  grid-template-columns: 56px 1fr;
  gap: 16px;
  padding: 20px 0;
  border-bottom: 1px solid var(--ink-line);
}

.orr-numbered__n {
  color: var(--color-ultramarine);
  padding-top: 4px;
}

.orr-numbered__title {
  font-family: var(--font-body);
  font-weight: 600;
  font-size: 1.125rem;
  margin: 0 0 4px;
}

.orr-numbered p {
  margin: 0;
  color: var(--ink-muted);
  max-width: 46ch;
}

/* ───────────────────────── 03 The orrery ───────────────────────── */
.orr-orrery__copy {
  display: flex;
  flex-direction: column;
  gap: 36px;
}

.orr-legend {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 14px;
}

.orr-legend li {
  display: grid;
  grid-template-columns: 9.5rem 1fr;
  gap: 16px;
  align-items: baseline;
  transition: opacity 400ms var(--ease-out);
}

.orr-legend li[data-lit="off"] {
  opacity: 0.28;
}

.orr-legend .orr-label {
  color: var(--color-bone);
}

.orr-legend li:last-child .orr-label {
  color: var(--color-amber);
}

.orr-legend p {
  margin: 0;
  color: var(--bone-muted);
  font-size: 0.975rem;
}

.orr-orrery__diagram {
  display: grid;
  place-items: center;
}

.orr-orbit {
  width: min(100%, 64vh, 620px);
  height: auto;
  overflow: visible;
}

.orr-orbit [data-show] {
  transition:
    opacity 500ms var(--ease-out),
    transform 500ms var(--ease-out),
    stroke-dashoffset 900ms var(--ease-out);
  transform-box: fill-box;
  transform-origin: center;
}

.orr-orbit [data-show="off"] {
  opacity: 0;
  transform: scale(0.6);
}

.orr-orbit__ring {
  fill: none;
  stroke: var(--bone-line);
  stroke-width: 1.5;
  stroke-dasharray: 1;
  stroke-dashoffset: 0;
}

.orr-orbit__ring[data-show="off"] {
  stroke-dashoffset: 1;
  transform: none;
}

.orr-orbit__ring--outer {
  stroke-dasharray: 0.006 0.008;
}

.orr-orbit__links line {
  stroke: color-mix(in oklab, var(--color-bone) 32%, var(--color-ink));
  stroke-width: 1;
}

.orr-orbit__links[data-show="off"] {
  transform: none;
}

.orr-orbit__agent {
  fill: var(--color-bone);
}

.orr-orbit__agent--accent {
  fill: var(--color-ultramarine);
}

.orr-orbit__core {
  fill: var(--color-bone);
}

.orr-orbit__pulse circle {
  fill: var(--color-amber);
}

/* ───────────────────────── 04 How it works ───────────────────────── */
.orr-steps {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 24px;
}

.orr-steps__item {
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 28px 0 0;
  border-top: 1px solid var(--color-ink);
}

.orr-steps__n {
  font-family: var(--font-display);
  font-size: 4.5rem;
  line-height: 0.8;
  color: var(--color-ultramarine);
}

.orr-steps__item p {
  margin: 0;
  color: var(--ink-muted);
  max-width: 34ch;
}

/* ───────────────────────── 05 Use cases ───────────────────────── */
.orr-cases__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 32px;
}

.orr-cases__item {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.orr-cases__item p {
  margin: 0;
  color: var(--ink-muted);
  font-size: 0.975rem;
}


/* ───────────────────────── 06 Results ───────────────────────── */
.orr-results__grid {
  display: grid;
  gap: 32px;
}

.orr-figure {
  border-top: 1px solid var(--color-ink);
  padding-top: 20px;
}

.orr-figure__value {
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(4.5rem, min(9vw, 13vh), 9rem);
  line-height: 0.9;
  letter-spacing: -0.03em;
  font-variant-numeric: tabular-nums;
}

.orr-figure__label {
  margin: 14px 0 0;
  max-width: 26ch;
  color: var(--ink-muted);
}

.orr-results__note {
  color: var(--ink-muted);
}

/* ───────────────────────── 07 Quotes ───────────────────────── */
.orr-visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

.orr-quotes__lead {
  position: relative;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 28px;
}

.orr-quotes__texture {
  position: absolute;
  top: 50%;
  left: -6%;
  transform: translateY(-50%);
  width: min(42vw, 520px, 58vh); /* capped by height too, so it never hangs past the slide */
  aspect-ratio: 1;
  opacity: 0.22;
  z-index: 0;
  pointer-events: none;
}

.orr-quotes__lead blockquote,
.orr-quotes__lead figcaption {
  position: relative;
  z-index: 1;
  margin: 0;
}

.orr-quotes__big {
  margin: 0;
  font-family: var(--font-display);
  font-style: italic;
  font-size: clamp(2rem, 3.8vw, 3.75rem);
  line-height: 1.08;
  letter-spacing: -0.01em;
  text-wrap: balance;
}

.orr-quotes figcaption {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.orr-quotes figcaption .orr-label {
  color: var(--ink-muted);
}

.orr-quotes__name {
  font-weight: 600;
}

.orr-quotes__rest {
  display: grid;
  gap: 28px;
}

.orr-quotes__small {
  margin: 0;
  padding-top: 20px;
  border-top: 1px solid var(--ink-line);
}

.orr-quotes__small blockquote {
  margin: 0 0 16px;
}

.orr-quotes__small p {
  margin: 0;
  font-size: 1.125rem;
}

/* ───────────────────────── 08 Pricing ───────────────────────── */
.orr-tiers {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 16px;
}

.orr-tier {
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 28px;
  border: 1px solid var(--ink-line);
  border-radius: 4px;
}

.orr-tier[data-featured] {
  background: var(--color-ink);
  color: var(--color-bone);
  border-color: var(--color-ink);
}

.orr-tier__head {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.orr-tier__head h3 {
  margin: 0;
}

.orr-tier__badge {
  color: var(--color-amber);
}

.orr-tier__price {
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(3rem, 4.4vw, 4.5rem);
  line-height: 1;
}

.orr-tier__price .orr-label {
  font-family: var(--font-mono);
  color: var(--ink-muted);
  margin-left: 6px;
  vertical-align: middle;
}

.orr-tier[data-featured] .orr-tier__price .orr-label,
.orr-tier[data-featured] .orr-tier__blurb {
  color: var(--bone-muted);
}

.orr-tier__blurb {
  margin: 0;
  color: var(--ink-muted);
}

.orr-tier__features {
  list-style: none;
  margin: 0 0 8px;
  padding: 0;
  display: grid;
  gap: 8px;
  flex: 1;
}

.orr-tier__features li {
  display: flex;
  align-items: center;
  gap: 10px;
}

.orr-tier__features svg {
  color: var(--color-ultramarine);
  flex: none;
}

.orr-tier[data-featured] .orr-tier__features svg {
  color: var(--color-amber);
}

.orr-tier .orr-btn {
  align-self: flex-start;
}

/* ───────────────────────── 09 Security ───────────────────────── */
.orr-claims {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0 32px;
}

.orr-claims li {
  padding: 18px 0;
  border-top: 1px solid var(--bone-line);
}

.orr-claims__title {
  margin: 0 0 4px;
  font-family: var(--font-body);
  font-weight: 600;
  font-size: 1.0625rem;
}

.orr-claims p {
  margin: 0;
  color: var(--bone-muted);
}

.orr-security__texture {
  display: none;
}

/* ───────────────────────── 10 CTA ───────────────────────── */
.orr-cta__copy {
  display: flex;
  flex-direction: column;
  gap: 28px;
}

.orr-cta__title {
  font-size: clamp(3.5rem, min(8vw, 12vh), 8.5rem);
}

.orr-form {
  display: grid;
  gap: 18px;
  padding: 28px;
  border: 1px solid var(--color-ink);
  border-radius: 4px;
  background: var(--color-bone);
}

.orr-form--sent {
  gap: 12px;
  min-height: 260px;
  align-content: center;
}

.orr-field {
  display: grid;
  gap: 8px;
}

.orr-field label {
  color: var(--ink-muted);
}

.orr-field input {
  height: 48px;
  padding: 0 14px;
  border: 1px solid var(--ink-line);
  border-radius: 2px;
  background: transparent;
  color: var(--color-ink);
  font: inherit;
  transition: border-color 160ms var(--ease-out);
}

.orr-field input:focus-visible {
  outline: none;
  border-color: var(--color-ultramarine);
  box-shadow: 0 0 0 1px var(--color-ultramarine);
}

.orr-field[data-invalid] input {
  border-color: var(--color-ink);
}

.orr-field__error {
  margin: 0;
  font-family: var(--font-mono);
  font-size: 0.75rem;
  color: var(--color-ultramarine);
}

.orr-form__submit {
  justify-self: start;
  margin-top: 6px;
}

.orr-cta__footer {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 20px;
  color: var(--ink-muted);
  padding-top: 20px;
  border-top: 1px solid var(--ink-line);
}

.orr-cta__footer a {
  color: inherit;
  text-decoration: none;
}

.orr-cta__footer a:hover {
  color: var(--color-ink);
}

/* ───────────────────────── Desktop layouts ───────────────────────── */
@media (min-width: 900px) {
  .orr-title__copy {
    grid-column: 1 / span 7;
    grid-row: 1;
    align-self: center;
  }
  .orr-title__art {
    grid-column: 8 / -1;
    grid-row: 1;
    align-self: center;
  }
  .orr-title__hint {
    display: block;
    grid-row: 2;
  }

  .orr-problem__art {
    grid-column: 1 / span 4;
    align-self: center;
  }
  .orr-problem__copy {
    grid-column: 6 / -1;
    align-self: center;
  }

  .orr-orrery__copy {
    grid-column: 1 / span 5;
    align-self: center;
  }
  .orr-orrery__diagram {
    grid-column: 6 / -1;
  }
  .orr-orrery .orr-eyebrow {
    grid-row: 1;
  }

  .orr-how__title {
    grid-column: 1 / span 9;
  }
  .orr-steps {
    grid-template-columns: repeat(3, 1fr);
    gap: 24px;
  }

  .orr-cases__title {
    grid-column: 1 / span 8;
  }
  .orr-cases__list {
    grid-template-columns: repeat(3, 1fr);
    gap: 24px;
  }

  .orr-results__title {
    grid-column: 1 / span 9;
  }
  .orr-results__grid {
    grid-template-columns: repeat(3, 1fr);
    gap: 24px;
  }

  .orr-quotes__lead {
    grid-column: 1 / span 7;
    align-self: center;
  }
  .orr-quotes__rest {
    grid-column: 9 / -1;
    align-self: center;
  }

  .orr-pricing__title {
    grid-column: 1 / span 9;
  }
  .orr-tiers {
    grid-template-columns: repeat(3, 1fr);
  }

  .orr-security__title {
    grid-column: 1 / span 7;
  }
  .orr-claims {
    grid-column: 1 / span 8;
    grid-template-columns: repeat(2, 1fr);
  }
  .orr-security__texture {
    display: block;
    grid-column: 9 / -1;
    grid-row: 2 / span 2;
    align-self: stretch;
    min-height: 100%;
  }
  .orr-security__texture img {
    height: 100%;
    object-fit: cover;
  }

  .orr-cta__copy {
    grid-column: 1 / span 6;
    align-self: center;
  }
  .orr-cta__form {
    grid-column: 8 / -1;
    align-self: center;
  }
}

/* Keynote mode: slide content builds in after the wipe. */
/* KEYNOTE: keep in sync with KEYNOTE_QUERY in deck/Deck.tsx */
@media (min-width: 900px) and (min-height: 760px) and (prefers-reduced-motion: no-preference) {
  .orr-reveal {
    transition:
      opacity 600ms var(--ease-out),
      transform 600ms var(--ease-out);
    transition-delay: calc(var(--i, 0) * 80ms + 280ms);
  }
  .orr-slide:not([data-state="active"]) .orr-reveal {
    opacity: 0;
    transform: translateY(18px);
    transition-delay: 0ms;
    transition-duration: 200ms;
  }
  /* Before the deck is ready (first paint), don't hide the first slide's content. */
  .orr-deck:not([data-ready]) .orr-reveal {
    transition: none;
  }
}

